	5 "Parent of head" 6 "Grandchild of head" 7 "Other relative" 8 "Non-relative" 9 "Husband of head"
* recode 1968, currently coded as: 1 = head, 2 = wife, 3 = child, 4 = sibling, 
*	5 = parent, 6 = grandchild, 7 = other relative, 8 = non-relative, 9 = N/A 	
replace hhmem1968 = . if inlist(hhmem1968, 9 )
gen relationhd1968 = hhmem1968  
* 1969 -1982 already coded correctly 
/*for y69-y82: 9	Husband of Head  isnot a N/A */
forval i = 1969/1982 { 
	gen relationhd`i' = hhmem`i'  
} 
* recode 1983 - 2017, currently coded as: 10 = head, 20's = wife, 30's = child, 40's = sibling, 
*	50's = parent, 60,65 = grandchildren, 66-69 = grandparent, 70's,95-97 = other relative, 
*	83,88,98 = non-relative, 9 = husband of head 
foreach i of numlist 1983/2017{ 
	capture confirm variable hhmem`i' 
	if !_rc  {  
		recode hhmem`i' (10 = 1) (20 22 = 2) (30/38 = 3) (40 47 48 = 4) ///
						(50 57 58 = 5) (60 65 = 6) (66/75 95 96 97 = 7) ///
						(83 88 98 = 8) (90 92 = 9 ) , gen(relationhd`i') 
	}
} 
* split off ; 1 splitoff, 0 not a splitoff
