/*  SECTION 1: cleaning data from webscrape: NAFTA_0.py			
    Notes: */
/**********************************************************************/



forval year = 1985(1)2010 {
import excel "$raw_data/news/News`year'.xlsx", sheet("data") firstrow clear
save "$working_data/News_`year'.dta", replace
}
//Appending news report years into one file
forval year = 1985(1)2009 {
append using "$working_data/News_`year'.dta"
}
save "$working_data/tvnews_nafta1.dta", replace
use "$working_data/tvnews_nafta1.dta", clear
//Creating Month and year numeric variables from date string
gen str year=substr(dates,-4,4), after(A)
destring year, replace
gen str month=substr(dates,-12,3),  after(A)
destring month, replace

//Ensuring dataset only has ABC, NBC and CBS Evening News
keep if inlist(station, "ABC Evening News", "NBC Evening News", "CBS Evening News")

//Generating nafta variable, which will be my dummy variable for whether a news report discusses a NAFTA topic: trade, imports, and jobs/unemployment, exluding trade center (for World Trade Center). 
gen nafta = 0
//takes the key topic words for NAFTA and search the news report abstract, info. If key term is present in string, will make the word topic variable value greater than zero. I use this fact to generate nafta dummy.
foreach t in Trade trade imports Imports Jobs jobs Employment employment {
gen `t' = strpos(info,"`t'")
}
replace  nafta = 1 if (Trade > 0 | trade > 0 | imports > 0 | Imports > 0 ) & ///
	(Jobs > 0 | jobs > 0 | Employment > 0 | employment > 0)

//takes key term we want to avoid "Trade Center" and search the news report abstract, info. If present in string, will make word topic variable value greater than zero. Use this fact to eliminate news reports that mention "Trade Center" from nafta dummy. 
gen TC = strpos(info,"Trade Center")
replace nafta = 0 if TC > 0

//By Year-station, sums the number of news reports that mention the NAFTA topic words in the abstract
bysort year station: egen tot_nafta_sta = total(nafta) 
//By Year-station, creates variable with total news reports (note that variable nafta is non-missing for all).
bysort year station: egen tot_sta_all = count(nafta) 

//decomposing the duration variable of news reporting and summing duration and days
gen str hrs=substr(duration,1,2)
gen str min=substr(duration,4,2)
gen str sec=substr(duration,7,2)
destring hrs min sec, force replace
gen duration_min = hrs*60 + min + sec/60
bysort year station: egen nafta_mins = total(nafta * duration_min)
bysort year station: egen total_mins = total(duration_min)

egen tag = tag(year station dates)
bysort year station: egen total_days = total(tag)
bysort station dates: egen nafta_day = max(nafta)
bysort year station: egen nafta_days = total(tag*nafta_day)

//Creating percentages 
*Percent of Minutes (raw)
gen perc_min_nafta = 100*(nafta_mins / total_mins)
*Percent of Total Stories
gen perc_news_nafta = 100*(tot_nafta_sta / tot_sta_all)
*Percent of News Days
gen perc_days_nafta = 100*(nafta_days / total_days)


//labeling variables
label var id "News Report Story ID"
label var station "Broadcast Station"
label var title "News Report Title"
label var info "News Report Abstract (Transcript not included)"
label var duration "Duration of News Report in hours, minutes, and seconds"
label var dates "Full Date of News Report"
label var nafta_mins "Total (raw) minutes by Year-station of reports where where trade/imports and jobs/employment were mentioned, excluding Trade Center"
label var nafta "1 = News Report's Abstract mentions where trade/imports and jobs/employment were mentioned, excluding Trade Center"
label var tot_nafta_sta "Total (raw) reports by Year-station of reports where where trade/imports and jobs/employment were mentioned, excluding Trade Center"
label var perc_min_nafta "Percent by Year-station of reporting minutes where trade/imports and jobs/employment were mentioned, excluding Trade Center"

