***** Project Location 
*** We have already defined a global macro in Build Dataset.do, which sets the project directory to where the Replication Package is located
*** on the user's local machine. However, if the current .do file is not executed in the same Stata session as the Build Dataset.do file, or 
*** if the global variables have been cleared, then uncomment the following line:


* SET PATH TO REPLICATION PACKAGE HERE (IN CASE RUNNING THIS FILE IN A NEW STATA SESSION OR IF GLOBAL VARIABLES HAVE BEEN CLEARED)
// global project_dir "/Users/gss2159/Downloads/Bruno_Downloads/AER/AER_ReplicationPackage"


*** The code will loop over each variation of the Model in the paper (Baseline, Bertrand, Cournot DRS, Cournot Fringe, Cournot Tradable, Cournot XOPR, Multi-Product, Input-Output)
local models Baseline Bertrand "Cournot DRS" "Cournot Fringe" "Cournot Tradable" "Cournot XOPR" "Multi-Product" "Input-Output"

foreach model in `models' {

*** Navigate to Folder
	cd "$project_dir/Data/Output/`model'"

*** Collect Model Data from csv files and save to .dta

	if "`model'" == "Multi-Product" {
		local first_year=1999
		}
	else {
		local first_year=1995
		}

	if regexm("`model'","Fringe") {
		local last_year=2019
		}
	else {
		local last_year=2021
		}

	local second_year=`first_year'+1

	// First Year
	import delimited "Model Data `first_year'.csv", encoding(ISO-8859-1) clear case(preserve)
	gen year= `first_year'
	save "Model Data.dta",replace

	// Iterate over other years
	forval year=`second_year'/`last_year' {
		import delimited "Model Data `year'.csv", encoding(ISO-8859-1) clear case(preserve)
		gen year=`year'
		append using "Model Data.dta"
		save "Model Data.dta",replace
		}

	// Reorder and save
		order gvkey year
		sort year gvkey
		save "Model Data.dta",replace


*** Collect Demand Elasticities from csv files and save to .dta
	if "`model'"!="Multi-Product" &  "`model'"!="Input-Output"  {
	// First Year
	import delimited "Elasticities `first_year'.csv", encoding(ISO-8859-1)clear case(preserve)
	gen year=`first_year'
	save "Elasticities.dta",replace
	// Iterate over other years
	forval year=`second_year'/1998 {
		import delimited "Elasticities `year'.csv", encoding(ISO-8859-1)clear case(preserve)
		gen year=`year'
		append using "Elasticities.dta"
		save "Elasticities.dta",replace
		}
	//// Reorder and save
		order gvkey_i gvkey_j year
		sort year gvkey_i gvkey_j
		save "Elasticities.dta",replace
	}

		gen year=`year'
		append using "Elasticities.dta"
		save "Elasticities.dta",replace
		}
	//// Reorder and save
		order gvkey_i gvkey_j year
		sort year gvkey_i gvkey_j
		save "Elasticities.dta",replace
	}

}

