if `combineFiles' {
	use temp/diabetesPats.dta, clear

	merge 1:m DEID_EDI_PN using temp/primeVm6benYear.dta
	keep if _merge==3
	drop _merge

	//Number of patient-years where patient is enrolled in Prime during the year and at some point during the sample period has a diabetes diagnosis.
	local obs = _N 

	merge 1:1 DEID_EDI_PN year using temp/diabetesTreats.dta
	drop if _merge==2
	drop _merge

	assert `obs' == _N

	//Replace treatment flags with 0s for individuals without treatments. 
	foreach var in diaCare1 diaCare2 diaCare3 `diaRet' `diaNeph' `diaNeuro' `diaCerebro' `diaCardio' `diaPvd' `diaMeta' nephTreat ckd4 esrd kidTrans {
		replace `var' = 0 if missing(`var')
		}

	merge 1:1 DEID_EDI_PN year using temp/diabetesMediCollapsed.dta
	drop if _merge==2
	drop _merge

	//Replace diabetes prescription variables with 0s for individuals without relevant prescription types.
	foreach var in diaCare4 diaCare4days diaCare4GenDays diaCare4Cdays diaCare4Ddays diaCare4Mdays diaCare4Rdays diaCare4Tdays diaCare4Vdays  {
		replace `var' = 0 if missing(`var')
		}

	merge 1:1 DEID_EDI_PN year using temp/mhsMH.dta
	drop if _merge==2
	drop _merge

	//Create measure of on/off base medical utilization.
	gen onOffPref=rvuOn/rvu
	replace onOffPref = 0.5 if missing(onOffPref)
	replace onOffPref = 1 if onOffPref>=0.5
	replace onOffPref = 0 if onOffPref<0.5

	assert onOffPref==1 | onOffPref==0

	//Number of inpatient days in a year should be limited to 365. Small number of obs exceed.
	foreach var in inpatdays inpatdaysOn inpatdaysOff inpatdaysL inpatdaysOnL inpatdaysOffL {
		replace `var' = 365 if `var'>365 & !missing(`var')
		}

	merge 1:1 DEID_EDI_PN year using temp/mhsComorbidity.dta
	drop if _merge==2
	drop _merge

	merge m:1 DEID_SPN_PN_ID using temp/physSpons.dta
	drop if _merge==2
	drop _merge

