	append using `prime'primeMHDpClin.dta

	foreach var of varlist tedni caper tedi sidr ancil rwp rvu inpatdays flagDp {
		replace `var' = 0 if missing(`var')
		}

	gen on = 1 if inlist(1, caper, sidr, ancil)
	gen off = 1 if inlist(1, tedni, tedi)

	gen rvuOn =  0
	replace rvuOn = rvu if on==1

	gen rvuOff =  0
	replace rvuOff = rvu if off==1

if `findDocs' == 1{
	capture confirm file `prime'physSpons.dta
	if _rc == 0 {
		erase `prime'physSpons.dta
		}
	local years "03 04 05 06 07 08 09 10 11 12 13"
	local months "01 02 03 04 05 06 07 08 09 10 11 12"
	foreach year of local years {
		foreach month of local months {
			use raw_data/vm6ben/vm6ben_fy`year'_fm`month'.dta, clear

			keep if DOD_OCC_CD!=""
			keep if PN_TYP_CD == "S" 

			gen yearDoc = 2000+`year'
			gen fYearDoc = yearDoc
			gen cYearDoc = fYearDoc
			replace cYearDoc = cYearDoc-1 if `month'<4

			gen fMonthDoc = `month'
			gen cMonthDoc = fMonthDoc + 9 
			replace cMonthDoc = cMonthDoc - 12 if cMonthDoc>12

			rename DEID_DOD_EDI_PN_ID DEID_EDI_PN

			keep DEID_SPN_PN_ID DOD_OCC_CD DEID_EDI_PN yearDoc fYearDoc cYearDoc fMonthDoc cMonthDoc D_AGE_QY 

			keep if substr(DOD_OCC_CD,1,2) == "6A"

			capture confirm file `prime'physSpons.dta
			if _rc == 0 {
				append using `prime'physSpons.dta
				}
			save `prime'physSpons.dta, replace
			}
		}

	use `prime'physSpons.dta, clear
	sort DEID_EDI_PN fYearDoc fMonthDoc
	by DEID_EDI_PN: generate n1 = _n
	by DEID_EDI_PN: generate n2 = _N 
	keep if n1 == 1
	rename n2 physMonths
	destring(D_AGE_QY), replace
	rename D_AGE_QY physAge
	/*Small number of physicians (7) have two separate sponsor codes. We drop them*/
	by DEID_SPN_PN_ID, sort: drop if _N==2
 	save `prime'physSpons.dta, replace
	}

