*create missing observations
*In case an observation is only seen in one year
*can replicate it for other years

local samples = "bartik train"
foreach A in `samples'{

	use "H:/data/liab_`A'.dta", clear

	bysort persnr: egen n = total(1)
	expand 2 if n == 1, gen(added)
	drop n
	label var added "Observation orignally missing in this year"
	replace wgt_year = 0 if added == 1
	cap replace wgt_year_norm = 0 if added == 1
	if "`A'" == "train" {
		replace year = -year +1999+2012 if added == 1  //switches 1999 and 2012
	}
	if "`A'" == "bartik" {
		replace year = -year +2004 + 2014 if added == 1  //switches 2004 and 2014
	}
	replace X_age = year - gebjahr if  added == 1
	foreach z of varlist Z* betnr idnum tentgelt_gr occ* ind ao_kreis {
		replace `z' = . if added == 1
	}

	save "H:/data/liab_`A'.dta", replace
}
